insert into public.products (slug, name, category, short_description, description, price, price_unit, price_is_starting, image_url, upload_kind, upload_required, sort_order) values
('passport-photo-prints','Passport Photo Prints','passport','Print-ready passport photos from your own picture.','Upload a clear front-facing photograph on a plain background. We crop, colour-correct and print to the standard 35 x 45 mm passport size. Collect the prints from your selected branch.',80,'per set of 8',false,'https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=1200&q=80','passport',true,10),
('studio-passport-session','Studio Passport Photo Session','passport','Professionally captured and printed at the studio.','Visit the studio and we photograph you under proper lighting on a white background, then print a set of 8 passport photos. Optionally upload a sample of the required format.',150,'per set of 8',false,'https://images.unsplash.com/photo-1527011046414-4781f1f94f8c?auto=format&fit=crop&w=1200&q=80','passport',false,20),
('visa-photos','Visa and Custom Size Photos','passport','Visa, exam and ID photos to any required size.','Tell us the size specification (for example 51 x 51 mm for US visa) in the notes and upload your photograph. We print to the exact requirement.',200,'per set of 6',false,'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=1200&q=80','passport',true,30),
('a4-photo-frame','A4 Photo Frame','frames','Your photograph printed and framed in A4.','A premium photo print in a classic black or gold-edged frame with glass front. Upload the photograph you want printed.',650,'per frame',false,'https://images.unsplash.com/photo-1513161455079-7dc1de15ef3e?auto=format&fit=crop&w=1200&q=80','frame',true,40),
('wooden-frame-12x18','12 x 18 Wooden Frame','frames','Large wooden frame for portraits and family photos.','Solid wood moulding with a high-quality laminated print. Ideal for wedding portraits and family photographs.',1250,'per frame',false,'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1200&q=80','frame',true,50),
('collage-frame','Collage Frame','frames','Up to 6 photographs arranged in one frame.','Upload up to six photographs and we design an elegant collage layout before printing and framing.',1800,'per frame',false,'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=1200&q=80','frame',true,60),
('flex-banner','Flex Banner Printing','banners','High-resolution flex banners printed to any size.','Upload your print-ready banner design or send your logo and reference photos and our designers will prepare it. Mention the size in the notes. Price is per square foot.',18,'per sq ft',false,'https://images.unsplash.com/photo-1612815154858-60aa4c59eaa6?auto=format&fit=crop&w=1200&q=80','banner',false,70),
('birthday-banner','Birthday Banner (6 x 4 ft)','banners','Personalised birthday banner with photos.','Includes custom design with the name, age and photographs. Upload photos and any reference designs you like.',900,'per banner',false,'https://images.unsplash.com/photo-1530103862676-de8c9debad1d?auto=format&fit=crop&w=1200&q=80','banner',false,80),
('shop-signage-banner','Shop Signage Banner','banners','Storefront and promotional signage banners.','Professional design and printing for shop boards and promotional banners. Upload your logo and existing designs.',1500,'per banner',true,'https://images.unsplash.com/photo-1626785774573-4b799315345d?auto=format&fit=crop&w=1200&q=80','banner',false,90),
('wedding-photography','Wedding Photography','events','Complete candid and traditional wedding coverage.','Full-day coverage by our photography team, including candid and traditional shots, edited high-resolution images and a highlights selection. Upload reference photos or your event schedule.',35000,'per event',true,'https://images.unsplash.com/photo-1610173827002-62c0f1f05d04?auto=format&fit=crop&w=1200&q=80','event',false,100),
('birthday-function-photography','Birthday Function Photography','events','Coverage for birthday parties and celebrations.','Photography for birthday functions with edited images delivered digitally. Upload reference photos or event requirements.',8000,'per event',true,'https://images.unsplash.com/photo-1464349095431-e9a21285b5f3?auto=format&fit=crop&w=1200&q=80','event',false,110),
('engagement-photography','Engagement Photography','events','Engagement ceremony and couple portraits.','Ceremony coverage plus a short couple portrait session. Upload reference photos for the style you prefer.',15000,'per event',true,'https://images.unsplash.com/photo-1605100804763-247f67b3557e?auto=format&fit=crop&w=1200&q=80','event',false,120),
('event-videography','Event Videography','events','Cinematic video coverage and highlight films.','Full HD and 4K video coverage with a cinematic highlights film and full-length edit. Upload your event plan or reference videos as PDF.',20000,'per event',true,'https://images.unsplash.com/photo-1601506521937-0121a7fc2a6b?auto=format&fit=crop&w=1200&q=80','event',false,130),
('premium-album-design','Premium Album Design','events','Hand-designed premium photo albums.','Professionally designed albums with premium paper and covers. Upload your selected photographs or reference layouts.',6500,'per album',true,'https://images.unsplash.com/photo-1452421822248-d4c2b47f0c81?auto=format&fit=crop&w=1200&q=80','event',false,140);
